select *
from sim_deudapoliza_sai
where id_proceso = 221;

select m.*, d.*
from sim_cooprop_crucereint_mae m
         inner join crucereintegros_ric d
                    on m.id_cruce_mae = d.id_cruce_mae
where m.id_proceso = 221;

select * from SIM_DEUDAPOLIZA_SAI WHERE TIPODOC = 'NT'
                                    AND NUMDOC IN ('900912179','805026417','805026417','900912179','900912179')
                                    AND NUMRIESGO IN ('406','2','74','453','291');

select TIPODOC, NUMDOC, NUMRIESGO, APLICADO_CRUCE
from SIM_DEUDAPOLIZA_SAI
WHERE NVL(APLICACION_WRS, 'N') = 'N'
  AND APLICADO_CRUCE > 0
  AND REGISTRADO_SERVICIO = 'S';

UPDATE SIM_DEUDAPOLIZA_SAI
SET APLICACION_WRS       = NULL,
    FECHA_APLICACION_WRS = NULL
WHERE TIPODOC = 'NT'
  AND NUMDOC IN ('900912179','805026417','805026417','900912179','900912179')
  AND NUMRIESGO IN ('2','74');



SELECT distinct NUM_POL1
FROM   A2000030
WHERE  COD_CIA = 3
  AND    COD_SECC = 4
  AND    COD_RAMO = 445
  AND    NRO_DOCUMTO = 805026417;

SELECT distinct NUM_POL1
FROM   A2000030
WHERE  COD_CIA = 3
  AND    COD_SECC = 4
  AND    COD_RAMO = 445
  AND    NRO_DOCUMTO = 900912179;

SELECT S.NUM_SINI,
       S.NUM_POL1,
       E.NRO_EXPED,
       R.TOTAL_LIQ
FROM A7000900 S,
     A7001000 E,
     A7001200 R
WHERE S.COD_CIA = 3
  AND S.COD_SECC = 4
  AND S.COD_RAMO = 445
  AND S.NUM_POL1 = 2560000001701
  AND S.COD_RIES = 406
  AND S.COD_CAUSA_BAJA IS NULL
  AND S.NRO_ORDEN_SINI =
      (SELECT MAX(S1.NRO_ORDEN_SINI)
       FROM A7000900 S1
       WHERE S1.COD_CIA = S.COD_CIA
         AND S1.COD_SECC = S.COD_SECC
         AND S1.NUM_SECU_SINI = S.NUM_SECU_SINI)
  AND E.COD_CIA = S.COD_CIA
  AND E.COD_SECC = S.COD_SECC
  AND E.NUM_SINI = S.NUM_SINI
  AND E.TIPO_EXPED = 'CAD'
  AND E.NRO_ORDEN_EXP =
      (SELECT MAX(E1.NRO_ORDEN_EXP)
       FROM A7001000 E1
       WHERE E1.NUM_SECU_EXPED = E.NUM_SECU_EXPED)
  AND R.NUM_SECU_EXPED = E.NUM_SECU_EXPED
  AND R.NRO_ORDEN_EXP = E.NRO_ORDEN_EXP
  AND R.TOTAL_LIQ > 0
ORDER BY FECHA_SINI;


